import{_ as a,a as t,c as n,ac as o}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第三册：培养技能 · Lesson 31 A lovable eccentric","description":"学习 非限定性定语从句，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第三册：培养技能 · Lesson 31 A lovable eccentric","description":"学习 非限定性定语从句，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第3册课时","summary":"学习 非限定性定语从句，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第三册：培养技能 · Lesson 30 The death of a ghost","link":"/life/english/new-concept/book-3/unit-02/lesson-030"},"next":{"text":"第三册：培养技能 · Lesson 32 A lost ship","link":"/life/english/new-concept/book-3/unit-02/lesson-032"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第三册：培养技能 · Lesson 30 The death of a ghost","link":"/life/english/new-concept/book-3/unit-02/lesson-030"},"next":{"text":"第三册：培养技能 · Lesson 32 A lost ship","link":"/life/english/new-concept/book-3/unit-02/lesson-032"}},"headers":[],"relativePath":"life/english/new-concept/book-3/unit-02/lesson-031.md","filePath":"life/english/new-concept/book-3/unit-02/lesson-031.md"}'),i={name:"life/english/new-concept/book-3/unit-02/lesson-031.md"};function l(s,e,r,h,c,d){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="第三册-培养技能-·-lesson-31-a-lovable-eccentric" tabindex="-1">第三册：培养技能 · Lesson 31 A lovable eccentric <a class="header-anchor" href="#第三册-培养技能-·-lesson-31-a-lovable-eccentric" aria-label="Permalink to &quot;第三册：培养技能 · Lesson 31 A lovable eccentric&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-3/contents">本册目录</a> · <a href="/life/english/new-concept/book-3/unit-02/overview">单元 2</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>从不寻常但可理解的生活习惯练习人物描写。与其称某人“古怪”，不如展示具体行动以及旁人的反应。学习非限定性定语从句补充背景，在不打断主线的情况下提供细节，并注意逗号可能改变句子指向的人群范围。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>eccentric</td><td>/ɪkˈsentrɪk/</td><td>adj.</td><td>古怪的</td><td>eccentric habits</td></tr><tr><td>habit</td><td>/ˈhæbɪt/</td><td>n.</td><td>习惯</td><td>an unusual habit</td></tr><tr><td>affection</td><td>/əˈfekʃən/</td><td>n.</td><td>喜爱</td><td>show affection</td></tr><tr><td>individual</td><td>/ˌɪndɪˈvɪdʒuəl/</td><td>n.</td><td>个人</td><td>a remarkable individual</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>have a habit of — 有做某事的习惯，后接 ing</li><li>be fond of — 喜欢，后接名词或动名词</li></ul><h2 id="语法讲解-非限定性定语从句" tabindex="-1">语法讲解：非限定性定语从句 <a class="header-anchor" href="#语法讲解-非限定性定语从句" aria-label="Permalink to &quot;语法讲解：非限定性定语从句&quot;">​</a></h2><p>非限定性定语从句用逗号与主句隔开，补充而不负责筛选指代对象。指人常用 who，指物用 which，表示所属用 whose，不能用 that，关系词也不能省略。限定性与非限定性的区别不是单纯停顿：my neighbours who cycle 指骑车的那部分邻居，my neighbours, who cycle, 对当前提到的全部邻居补充骑车信息。写人物简介时，名字已经明确身份，补充经历往往适合非限定从句，但仍要看是否存在同名或范围限制。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>Mr Vale, who repairs clocks for fun, keeps a tiny workshop in his kitchen.</p></blockquote><p>韦尔先生以修钟为乐，他在厨房里设有一个小工作区。</p><p>who 从句补充已明确人物的爱好；主句骨架为 Mr Vale keeps a tiny workshop。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>Mr Vale, that repairs clocks, ... 不符合非限定从句规则，应使用 who，并补足完整主句。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>读插入从句时前后略停，先只读主句骨架，再读全句，检查读者能否始终跟住 keeps 或 makes 这个主要谓语。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>Mrs Lane, who collects broken umbrellas, makes colourful shopping bags. She hangs each new bag on the garden fence. Visitors often stop to ask how it was made.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>写三句描绘一位有特别爱好的邻居，至少一处用非限定从句。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>具体动作呈现性格，补充从句交代材料来源，人物形象自然形成。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>删去例句中的插入从句，主句是什么？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Mr Vale keeps a tiny workshop in his kitchen.</p><p><strong>解析：</strong> 非限定从句不影响主句完整性。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>填空：The garden, ___ belongs to Anna, opens on Sundays.（which/that）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> which</p><p><strong>解析：</strong> 逗号隔开的非限定从句不用 that。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>whose 主要表示什么关系？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 所属关系。</p><p><strong>解析：</strong> 如 whose bicycle 表示某人的自行车。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：非限定性定语从句。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-3/unit-02/grammar">单元语法</a> · <a href="/life/english/new-concept/book-3/unit-02/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-3/unit-02/review">单元自测</a></p><p><a href="/life/english/new-concept/book-3/unit-02/lesson-030">上一课</a> · <a href="/life/english/new-concept/book-3/unit-02/overview">单元目录</a> · <a href="/life/english/new-concept/book-3/unit-02/lesson-032">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=a(i,[["render",l]]);export{u as __pageData,b as default};
